8	interface QualityReportState {
9	  report: QualityReport | null;
10	  isLoading: boolean;
11	  showDismissed: boolean;
12	  refreshReport: (treeId?: string) => Promise<void>;
13	  setShowDismissed: (show: boolean) => void;
14	  dismissIssue: (issueId: string) => Promise<void>;
15	  restoreIssue: (issueId: string) => Promise<void>;
16	  resolveBridgeDrift: (
17	    memberId: string,
18	    direction: "push" | "pull",
19	  ) => Promise<void>;
20	  mergeMembers: (
21	    keepId: string,
22	    removeId: string,
23	    fields: Partial<Record<string, MergeFieldChoice>>,
24	  ) => Promise<void>;
25	  clear: () => void;
26	}
27	
28	export const useQualityReportStore = create<QualityReportState>((set, get) => ({
29	  report: null,
30	  isLoading: false,
31	  showDismissed: false,
32	
33	  refreshReport: async (treeId = activeTreeId()) => {
34	    if (!treeId) {
35	      set({ report: null });
36	      return;
37	    }
38	    set({ isLoading: true });
39	    try {
40	      const report = await TreeService.getQualityReport(treeId);
41	      if (!isActiveTree(treeId)) return; // tree switched/disconnected mid-flight — drop stale data
42	      set({ report });
43	    } finally {
44	      set({ isLoading: false });
45	    }
46	  },
47	
48	  setShowDismissed: (show: boolean) => set({ showDismissed: show }),
49	
50	  dismissIssue: async (issueId: string) => {
51	    const treeId = activeTreeId();
52	    if (!treeId) return;
53	    await TreeService.dismissQualityIssue(treeId, issueId);
54	    await get().refreshReport(treeId);
55	  },
56	
57	  restoreIssue: async (issueId: string) => {
58	    const treeId = activeTreeId();
59	    if (!treeId) return;
60	    await TreeService.restoreQualityIssue(treeId, issueId);
61	    await get().refreshReport(treeId);
62	  },
63	
64	  // Resolve bridge-person drift by copying fields across the tree link
65	  // ("push" = this tree wins, "pull" = the linked tree wins), then reload the
66	  // report and — on pull — the members, whose fields just changed. Errors
67	  // (e.g. 403 without write access to the linked tree) propagate to the view.
68	  resolveBridgeDrift: async (memberId: string, direction: "push" | "pull") => {
69	    const treeId = activeTreeId();
70	    if (!treeId) return;
71	    await TreeService.resolveBridgeDrift(treeId, memberId, direction);
72	    const tasks: Promise<void>[] = [get().refreshReport(treeId)];
73	    if (direction === "pull") {
74	      tasks.push(useMemberStore.getState().refreshMembers(treeId));
75	    }
76	    await Promise.all(tasks);
77	  },
78	
79	  // Merge two members of the tree in place (#729): the report and member
80	  // list both change shape (a duplicate finding disappears, a member is
81	  // gone), so refresh both. Errors (e.g. the 400 cycle guard) propagate to
82	  // the dialog, which maps them to a specific message.
83	  mergeMembers: async (keepId, removeId, fields) => {
84	    const treeId = activeTreeId();
85	    if (!treeId) return;
86	    await TreeService.mergeMembers(treeId, {
87	      keep_id: keepId,
88	      remove_id: removeId,
89	      fields,
90	    });
91	    await Promise.all([
92	      get().refreshReport(treeId),
93	      useMemberStore.getState().refreshMembers(treeId),
94	    ]);
95	  },
96	
97	  clear: () => set({ report: null, showDismissed: false }),
98	}));
